import {useEffect,useState} from 'react';
import {Download,Eye,FileText,Plus,RefreshCw,Share2,ShieldCheck} from 'lucide-react';
import {createProgressReport,downloadProgressReport,generateProgressReport,listProgressReports,previewProgressReport,revokeProgressReport,shareProgressReport} from '../../lib/practiceOperationsApi';

const reportTypes=['CLIENT_PROGRESS_REPORT','PROGRAMME_COMPLETION_REPORT','ASSESSMENT_PROGRESS_REPORT','REHAB_PROGRESS_REPORT','COACHING_PROGRESS_REPORT','WELLNESS_PROGRESS_REPORT','THERAPY_PROGRESS_REPORT','BEHAVIOUR_PROGRESS_REPORT','DIABETES_EDUCATION_PROGRESS_REPORT','OT_PROGRESS_REPORT'];
const sections=['goals','sessions','assessments','progress','plans','homework','milestones','consultant_summary'];
const today=()=>new Date().toISOString().slice(0,10);const monthAgo=()=>new Date(Date.now()-30*86400000).toISOString().slice(0,10);
export function ExternalProgressReports({clients=[],clientId='',profession='OTHER'}){
  const[items,setItems]=useState([]),[state,setState]=useState('loading'),[error,setError]=useState(''),[wizard,setWizard]=useState(false),[preview,setPreview]=useState(null),[created,setCreated]=useState(null);
  const[form,setForm]=useState({client_id:clientId,profession_code:profession,report_type:'CLIENT_PROGRESS_REPORT',title:'Client progress report',period_start:monthAgo(),period_end:today(),included_sections:['goals','sessions','progress','milestones','consultant_summary'],consultant_summary:''});
  const load=async()=>{setState('loading');setError('');try{const result=await listProgressReports(clientId);setItems(result.items||[]);setState('ready')}catch(reason){setError(reason.message||'Progress reports could not be loaded.');setState('error')}};useEffect(()=>{void load()},[clientId]);
  const create=async event=>{event.preventDefault();setError('');try{const result=await createProgressReport(form);setCreated(result);const view=await previewProgressReport(result.id);setPreview(view.preview)}catch(reason){setError(reason.message||'Report draft could not be created.')}};
  const generate=async()=>{try{await generateProgressReport(created.id);setWizard(false);setCreated(null);setPreview(null);await load()}catch(reason){setError(reason.message||'Report generation failed.')}};
  const action=async(fn,item)=>{try{await fn(item.id);await load()}catch(reason){setError(reason.message||'Report action failed.')}};
  return <section className="space-y-5"><header className="flex flex-col justify-between gap-3 sm:flex-row sm:items-end"><div><p className="text-xs font-bold uppercase tracking-widest text-blue-700">Insights</p><h2 className="mt-1 text-3xl font-bold">Progress reports</h2><p className="mt-2 text-sm text-slate-600">Profession-specific, source-labelled reports. Drafts remain private and generated versions are immutable.</p></div><button onClick={()=>setWizard(true)} className="min-h-11 rounded-xl bg-slate-950 px-4 font-semibold text-white"><Plus className="mr-2 inline" size={17}/>Generate progress report</button></header>
    {error&&<p role="alert" className="rounded-xl bg-red-50 p-4 text-sm text-red-800">{error}</p>}
    {state==='loading'?<div className="h-40 animate-pulse rounded-3xl bg-white" aria-label="Loading progress reports"/>:state==='error'?<button onClick={load} className="min-h-11 rounded-xl border px-4"><RefreshCw className="mr-2 inline" size={16}/>Retry</button>:items.length?<div className="grid gap-4 lg:grid-cols-2">{items.map(item=><article key={item.id} className="rounded-3xl border bg-white p-5"><div className="flex justify-between gap-3"><div><p className="font-bold">{item.title}</p><p className="mt-1 text-sm text-slate-500">{item.report_type.replaceAll('_',' ')} · {item.period_start} to {item.period_end}</p></div><span className="h-fit rounded-full bg-blue-50 px-3 py-1 text-xs font-bold text-blue-800">{item.status}</span></div><p className="mt-3 text-xs text-slate-500">Version {item.current_version} · sections: {item.included_sections.join(', ')}</p><div className="mt-4 flex flex-wrap gap-2">{item.status==='DRAFT'&&<button onClick={async()=>{setCreated(item);setPreview((await previewProgressReport(item.id)).preview);setWizard(true)}} className="min-h-11 rounded-xl border px-3 text-sm font-semibold"><Eye className="mr-1 inline" size={15}/>Preview</button>}{item.current_version>0&&<><button onClick={()=>downloadProgressReport(item.id,'PDF')} className="min-h-11 rounded-xl border px-3 text-sm font-semibold"><Download className="mr-1 inline" size={15}/>PDF</button><button onClick={()=>downloadProgressReport(item.id,'DOCX')} className="min-h-11 rounded-xl border px-3 text-sm font-semibold">DOCX</button></>}{item.status==='GENERATED'&&<button onClick={()=>action(shareProgressReport,item)} className="min-h-11 rounded-xl bg-blue-700 px-3 text-sm font-semibold text-white"><Share2 className="mr-1 inline" size={15}/>Share to portal</button>}{item.status==='SHARED'&&<button onClick={()=>action(revokeProgressReport,item)} className="min-h-11 rounded-xl px-3 text-sm font-semibold text-red-700">Revoke</button>}</div></article>)}</div>:<div className="rounded-3xl border border-dashed bg-white p-8 text-center"><FileText className="mx-auto text-slate-400"/><p className="mt-3 font-semibold">No progress reports yet</p><p className="mt-1 text-sm text-slate-500">This is a confirmed empty state; no report has been fabricated.</p></div>}
    {wizard&&<div className="fixed inset-0 z-50 grid place-items-center bg-slate-950/50 p-4" onClick={()=>setWizard(false)}><form onSubmit={create} onClick={event=>event.stopPropagation()} role="dialog" aria-modal="true" aria-labelledby="report-wizard-title" className="max-h-[94vh] w-full max-w-3xl overflow-y-auto rounded-3xl bg-white p-6"><h3 id="report-wizard-title" className="text-xl font-bold">Progress report builder</h3><ol className="mt-3 flex gap-2 overflow-x-auto text-xs font-semibold text-slate-500">{['Type','Period','Sections','Preview','Generate','Share'].map((step,index)=><li key={step} className="shrink-0 rounded-full bg-slate-100 px-3 py-2">{index+1}. {step}</li>)}</ol>{!preview?<><div className="mt-6 grid gap-4 sm:grid-cols-2"><label className="text-sm font-semibold">Client<select required value={form.client_id} onChange={e=>setForm({...form,client_id:e.target.value})} className="mt-2 min-h-12 w-full rounded-xl border px-3"><option value="">Select client</option>{clients.map(client=><option key={client.id} value={client.id}>{client.displayName}</option>)}</select></label><label className="text-sm font-semibold">Report type<select value={form.report_type} onChange={e=>setForm({...form,report_type:e.target.value})} className="mt-2 min-h-12 w-full rounded-xl border px-3">{reportTypes.map(type=><option key={type}>{type}</option>)}</select></label><label className="text-sm font-semibold">From<input type="date" required value={form.period_start} onChange={e=>setForm({...form,period_start:e.target.value})} className="mt-2 min-h-12 w-full rounded-xl border px-3"/></label><label className="text-sm font-semibold">To<input type="date" required value={form.period_end} onChange={e=>setForm({...form,period_end:e.target.value})} className="mt-2 min-h-12 w-full rounded-xl border px-3"/></label></div><fieldset className="mt-5"><legend className="font-semibold">Sections</legend><div className="mt-2 grid gap-2 sm:grid-cols-2">{sections.map(section=><label key={section} className="flex min-h-11 items-center gap-2 rounded-xl border p-3 text-sm"><input type="checkbox" checked={form.included_sections.includes(section)} onChange={e=>setForm({...form,included_sections:e.target.checked?[...form.included_sections,section]:form.included_sections.filter(value=>value!==section)})}/>{section.replaceAll('_',' ')}</label>)}</div></fieldset><label className="mt-5 block text-sm font-semibold">Consultant summary<textarea value={form.consultant_summary} onChange={e=>setForm({...form,consultant_summary:e.target.value})} className="mt-2 min-h-28 w-full rounded-xl border p-3" placeholder="Write a factual summary. No diagnosis is generated."/></label><button className="mt-6 min-h-12 w-full rounded-xl bg-blue-700 font-semibold text-white">Create preview</button></>:<div className="mt-6"><div className="rounded-2xl border bg-slate-50 p-5"><h4 className="text-xl font-bold">{preview.title}</h4><p className="mt-1 text-sm text-slate-500">{preview.period_start} to {preview.period_end}</p>{preview.consultant_summary&&<p className="mt-4 text-sm">{preview.consultant_summary}</p>}<div className="mt-5 space-y-4">{preview.sections.map(section=><section key={section.key}><h5 className="font-semibold">{section.title}</h5>{section.items.length?<ul className="mt-2 space-y-1 text-sm">{section.items.map((item,index)=><li key={index}>{item.label}: {item.value} <span className="text-xs text-slate-400">[{item.provenance.replaceAll('_',' ')}]</span></li>)}</ul>:<p className="mt-1 text-sm text-slate-500">No records in this period.</p>}</section>)}</div></div><p className="mt-4 flex gap-2 rounded-xl bg-emerald-50 p-3 text-sm text-emerald-900"><ShieldCheck className="shrink-0" size={18}/>Private notes, raw session notes, draft plans, and internal intelligence are excluded.</p><button type="button" onClick={generate} className="mt-5 min-h-12 w-full rounded-xl bg-emerald-700 font-semibold text-white">Generate immutable PDF + DOCX</button></div>}<button type="button" onClick={()=>{setWizard(false);setPreview(null);setCreated(null)}} className="mt-3 min-h-11 w-full rounded-xl border font-semibold">Close</button></form></div>}
  </section>
}
